source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python -c "
import json, re
from collections import Counter
tasks = Counter()
with open('/root/autodl-tmp/expert_trajectories/expert_trajectories.jsonl') as f:
    for line in f:
        d = json.loads(line)
        for m in d['messages']:
            if m['role'] == 'user' and 'Your task is to:' in m['content']:
                task = m['content'].split('Your task is to:')[1].strip().split('.')[0].strip()
                # categorize
                if 'cool' in task:
                    tasks['pick_cool_then_place'] += 1
                elif 'clean' in task:
                    tasks['pick_clean_then_place'] += 1
                elif 'heat' in task:
                    tasks['pick_heat_then_place'] += 1
                elif 'look at' in task:
                    tasks['look_at_obj_in_light'] += 1
                elif 'put' in task or 'place' in task:
                    tasks['pick_and_place'] += 1
                else:
                    tasks['other'] += 1
                break
total = sum(tasks.values())
print(f'Total trajectories with task: {total}')
for k,v in sorted(tasks.items(), key=lambda x:-x[1]):
    print(f'  {k}: {v} ({v*100/total:.1f}%)')
"
